def search_users(terms: list[str]) -> list[dict]:
    """Return users whose name contains every term as a case-insensitive substring."""
    lowered = [term.lower() for term in terms]
    return [user for user in store.list_users() if all(term in user["name"].lower() for term in lowered)]
